using Kaff.Domain.DailyLogs;

namespace Kaff.Api.Features.DailyLogs.RecordField;

/// <summary>A single-valued field. Check-in and check-out take no text.</summary>
/// <param name="EntryId">Generated by the device, so a retried sync is recognised and not counted twice.</param>
/// <param name="OccurredAt">When it happened on site, with the device's offset. Decides which day the entry belongs to.</param>
public sealed record Request(Guid? EntryId, DateTimeOffset? OccurredAt, DailyLogField Field, string? Text);
